package com.example.flashcardapp.main

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.CheckBox
import androidx.recyclerview.widget.RecyclerView
import com.example.flashcardapp.R
import com.example.flashcardapp.data.TopicWithCount

// changes: now we store TopicWithCount
class TopicSelectionAdapter(private val topics: List<TopicWithCount>) :
    RecyclerView.Adapter<TopicSelectionAdapter.TopicViewHolder>() {

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): TopicViewHolder {
        val view = LayoutInflater.from(parent.context).inflate(R.layout.item_topic_selection, parent, false)
        return TopicViewHolder(view)
    }

    override fun onBindViewHolder(holder: TopicViewHolder, position: Int) {
        val topicWC = topics[position]
        // show count next to the name
        val label = "${topicWC.name} (${topicWC.cardCount})"

        holder.cbTopic.text = label
        holder.cbTopic.isChecked = topicWC.selected
        holder.cbTopic.setOnCheckedChangeListener { _, isChecked ->
            topicWC.selected = isChecked
        }
    }

    override fun getItemCount(): Int {
        return topics.size
    }

    // Return the list (for saving) after user toggles or individually checks/unchecks.
    fun getSelectedTopics(): List<TopicWithCount> {
        return topics
    }

    // NEW: Check if everything is selected
    fun areAllSelected(): Boolean {
        return topics.all { it.selected }
    }

    // NEW: Select all
    fun selectAll() {
        for (t in topics) {
            t.selected = true
        }
        notifyDataSetChanged()
    }

    // NEW: Deselect all
    fun deselectAll() {
        for (t in topics) {
            t.selected = false
        }
        notifyDataSetChanged()
    }

    class TopicViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        val cbTopic: CheckBox = itemView.findViewById(R.id.cb_topic)
    }
}

FlashcardUtils.content:
package com.example.flashcardapp.util;

import com.example.flashcardapp.data.Flashcard;
import com.example.flashcardapp.data.Topic;

import org.json.JSONArray;
import org.json.JSONObject;
import java.util.ArrayList;
import java.util.List;

public class FlashcardUtils {

    public static List<Flashcard> parseFlashcardsFromJson(String jsonString) throws Exception {
        List<Flashcard> flashcards = new ArrayList<>();

        try {
            JSONArray questionsArray = new JSONArray(jsonString);

            for (int i = 0; i < questionsArray.length(); i++) {
                JSONObject questionObj = questionsArray.getJSONObject(i);
                Flashcard flashcard = new Flashcard(
                    questionObj.getString("question"),
                    questionObj.getString("answer")
                );
                flashcard.setSearchTerm(questionObj.optString("searchTerm", ""));
                flashcard.setUserNote(questionObj.optString("userNote", ""));

                // Parse topics from JSON
                JSONArray topicsArray = questionObj.optJSONArray("topics");
                if (topicsArray != null) {
                    List<String> topicNames = new ArrayList<>();
                    for (int j = 0; j < topicsArray.length(); j++) {
                        String topicName = topicsArray.getString(j);
                        topicNames.add(topicName);
                    }
                    // Store them in our transient property
                    flashcard.setTopicNames(topicNames);
                }

                flashcards.add(flashcard);
            }
        } catch (Exception e) {
            throw new Exception("Failed to parse JSON string into Flashcards", e);
        }

        return flashcards;
    }
}

