package com.example.flashcardapp.viewmodel

import androidx.lifecycle.MutableLiveData
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.flashcardapp.data.Flashcard
import com.example.flashcardapp.data.FlashcardRepository
import com.example.flashcardapp.data.Topic
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

class EditFlashcardViewModel(
    private val repository: FlashcardRepository,
    private val flashcardId: Int
) : ViewModel() {

    val flashcardLiveData = MutableLiveData<Flashcard?>()
    private val topicCache = mutableMapOf<String, Topic>()

    init {
        // Immediately load the flashcard and the topic cache
        loadFlashcard()
        preloadTopics()
    }

    private fun loadFlashcard() {
        viewModelScope.launch(Dispatchers.IO) {
            val fc = repository.getFlashcardById(flashcardId)
            if (fc != null) {
                // changes: also load topics
                val topicList = repository.getTopicsForFlashcard(fc.id)
                // convert them to e.g. comma separated names
                val names = topicList.joinToString(", ") { it.name }
                // store them in the flashcard's transient property or userNote or whatever
                fc.topicNames = topicList.map { it.name }
                // optionally, if you want to show in 'etTopics', let's do that
            }
            withContext(Dispatchers.Main) {
                flashcardLiveData.value = fc
            }
        }
    }

    private fun preloadTopics() {
        viewModelScope.launch(Dispatchers.IO) {
            val allTopics = repository.getAllTopics()
            for (topic in allTopics) {
                topicCache[topic.name] = topic
            }
        }
    }

    fun updateFlashcard(
        question: String,
        answer: String,
        searchTerm: String,
        userNote: String,
        topicNames: String,
        onComplete: () -> Unit
    ) {
        val currentFc = flashcardLiveData.value ?: return
        currentFc.question = question
        currentFc.answer = answer
        currentFc.searchTerm = searchTerm
        currentFc.userNote = userNote

        viewModelScope.launch(Dispatchers.IO) {
            repository.updateFlashcard(currentFc)

            // If we have comma-separated topic names, associate them
            if (topicNames.isNotEmpty()) {
                // First remove old crossRefs if you want them replaced
                repository.deleteCrossRefsForFlashcard(currentFc.id)

                val topicArray = topicNames.split(",")
                for (topicName in topicArray) {
                    val trimmed = topicName.trim()
                    if (trimmed.isNotEmpty()) {
                        val topic = getOrInsertTopicFromCache(trimmed)
                        repository.associateFlashcardWithTopic(currentFc.id, topic.id)
                    }
                }
            }

            withContext(Dispatchers.Main) {
                onComplete()
            }
        }
    }

    fun deleteFlashcard(onDeleted: () -> Unit) {
        val currentFc = flashcardLiveData.value ?: return
        viewModelScope.launch(Dispatchers.IO) {
            repository.deleteFlashcard(currentFc)
            withContext(Dispatchers.Main) {
                onDeleted()
            }
        }
    }

    private suspend fun getOrInsertTopicFromCache(topicName: String): Topic {
        val cached = topicCache[topicName]
        if (cached != null) {
            return cached
        }
        val found = repository.getTopicByName(topicName)
        val actual = found ?: repository.insertTopic(Topic(topicName))
        topicCache[topicName] = actual
        return actual
    }

    // changes: new function to remove old crossRefs if desired.
    suspend fun deleteCrossRefsForFlashcard(flashcardId: Int) {
        repository.deleteCrossRefsForFlashcard(flashcardId)
    }
}

